import { Box, Container, Stack, Typography } from "@mui/material";
import masterData from "../../data/masterData.json";
import { getIcon } from "../../utils/iconMap";
import LeadFormCard from "./LeadFormCard";
import type { Specialty } from "../../types/fellowship";

interface HeroSectionProps {
  specialty?: Specialty | null;
}

export default function HeroSection({ specialty = null }: HeroSectionProps) {
  const { brand, hero } = masterData;

  const headlineBefore = specialty?.headlineBefore || hero.headlineBefore;
  const headlineHighlight = specialty?.headlineHighlight || hero.headlineHighlight;
  const subheadline = specialty?.subheadline || hero.subheadline;
  const description = specialty?.heroDescription || hero.description;
  const fullHeroImage = specialty?.heroImage || hero.image;

  return (
    <Box
      sx={{
        position: "relative",
        overflow: "hidden",
        background: "linear-gradient(180deg, #EAF3FF 0%, #F4F9FF 42%, #FFFFFF 100%)",
        minHeight: { xs: "auto", md: 620, lg: 660 },
      }}
    >
      <Box
        sx={{
          position: "absolute",
          inset: 0,
          opacity: 0.18,
          backgroundImage: "radial-gradient(circle, rgba(0,86,210,0.28) 1px, transparent 1px)",
          backgroundSize: "22px 22px",
          pointerEvents: "none",
        }}
      />

      {/* DOCTOR — true center (between text & form), not on the right */}
      <Box
        key={fullHeroImage}
        sx={{
          display: { xs: "none", md: "flex" },
          position: "absolute",
          // sit in the middle gap — left of the form column
          left: { md: "42%", lg: "44%" },
          bottom: 0,
          transform: "translateX(-50%)",
          width: { md: 360, lg: 400, xl: 430 },
          height: { md: 540, lg: 580 },
          zIndex: 1,
          justifyContent: "center",
          alignItems: "flex-end",
          pointerEvents: "none",
        }}
      >
        <Box
          component="img"
          src={fullHeroImage}
          alt={specialty?.name || "Doctor"}
          sx={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
            // crop so the person fills this center frame
            objectPosition: "70% top",
          }}
        />
      </Box>

      <Container
        maxWidth="lg"
        sx={{ position: "relative", zIndex: 2, pt: { xs: 2, md: 2.5 }, pb: { xs: 4, md: 0 } }}
      >
        <Stack direction="row" alignItems="center" spacing={1.1} sx={{ mb: { xs: 2.5, md: 2.5 } }}>
          <Box component="img" src={brand.logo} alt={brand.name} sx={{ width: 34, height: 34 }} />
          <Typography sx={{ fontWeight: 800, fontSize: 14, letterSpacing: "0.08em", color: "#0B1F3A" }}>
            {brand.name}
          </Typography>
        </Stack>

        <Box
          sx={{
            display: "grid",
            gridTemplateColumns: { xs: "1fr", md: "1fr minmax(320px, 400px)" },
            gap: { xs: 3, md: 4 },
            alignItems: "start",
            minHeight: { md: 540, lg: 580 },
          }}
        >
          <Box sx={{ position: "relative", zIndex: 3, maxWidth: 460, pt: { md: 1 } }}>
            <Typography
              sx={{
                color: "#0056D2",
                fontWeight: 700,
                fontSize: 11,
                letterSpacing: "0.14em",
                mb: 1.5,
              }}
            >
              {specialty ? specialty.name.toUpperCase() : brand.eyebrow}
            </Typography>

            <Typography
              component="h1"
              sx={{
                fontWeight: 800,
                color: "#0B1F3A",
                fontSize: { xs: "1.7rem", sm: "2.1rem", md: "2.35rem", lg: "2.5rem" },
                lineHeight: 1.15,
                mb: 1.5,
                letterSpacing: "-0.02em",
              }}
            >
              {headlineBefore}
              <Box component="span" sx={{ color: "#0056D2" }}>
                {headlineHighlight}
              </Box>
            </Typography>

            <Typography sx={{ fontWeight: 700, color: "#0B1F3A", fontSize: { xs: 15, md: 17 }, mb: 1.25 }}>
              {subheadline}
            </Typography>

            <Box sx={{ position: "relative", mb: 3, maxWidth: 400 }}>
              <Typography sx={{ color: "#5A6B80", fontSize: { xs: 13.5, md: 14.5 }, lineHeight: 1.7 }}>
                {description}
              </Typography>
              <Typography
                sx={{
                  display: { xs: "none", lg: "block" },
                  position: "absolute",
                  right: -80,
                  top: 6,
                  width: 110,
                  fontFamily: "'Dancing Script', cursive",
                  fontSize: 18,
                  lineHeight: 1.15,
                  color: "#0056D2",
                  fontWeight: 700,
                  transform: "rotate(-10deg)",
                  whiteSpace: "pre-line",
                  textAlign: "center",
                }}
              >
                {hero.scriptText}
              </Typography>
            </Box>

            {/* Mobile doctor — centered */}
            <Box sx={{ display: { xs: "flex", md: "none" }, justifyContent: "center", mb: 2.5 }}>
              <Box
                component="img"
                key={`m-${fullHeroImage}`}
                src={fullHeroImage}
                alt="Doctor"
                sx={{
                  width: "75%",
                  maxWidth: 300,
                  height: 340,
                  objectFit: "cover",
                  objectPosition: "72% top",
                  borderRadius: 3,
                }}
              />
            </Box>

            <Stack
              direction="row"
              flexWrap="wrap"
              useFlexGap
              spacing={{ xs: 2, md: 2.5 }}
              alignItems="center"
              sx={{ mb: 2 }}
            >
              {hero.stats.map((stat) => {
                const Icon = getIcon(stat.icon);
                return (
                  <Stack key={stat.id} direction="row" spacing={0.9} alignItems="center">
                    <Box
                      sx={{
                        width: 34,
                        height: 34,
                        borderRadius: "50%",
                        bgcolor: "#E8F1FF",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                      }}
                    >
                      <Icon sx={{ color: "#0056D2", fontSize: 18 }} />
                    </Box>
                    <Typography sx={{ fontSize: 12.5, fontWeight: 700, color: "#0B1F3A" }}>
                      {stat.value ? (
                        <>
                          <Box component="span" sx={{ color: "#0056D2" }}>
                            {stat.value}
                          </Box>{" "}
                          {stat.label}
                        </>
                      ) : (
                        stat.label
                      )}
                    </Typography>
                  </Stack>
                );
              })}
            </Stack>

            <Stack
              direction="row"
              alignItems="center"
              spacing={1.25}
              sx={{
                display: "inline-flex",
                bgcolor: "#fff",
                border: "1px solid #E0EAF6",
                borderRadius: "12px",
                px: 1.5,
                py: 0.9,
                boxShadow: "0 4px 16px rgba(0,86,210,0.08)",
                mb: { md: 3 },
              }}
            >
              <Box component="img" src={hero.cpdBadge} alt="CPD" sx={{ width: 38, height: 38 }} />
              <Box>
                <Typography sx={{ fontSize: 12, fontWeight: 700, color: "#0B1F3A" }}>
                  {hero.cpdLabel}
                </Typography>
                {hero.cpdSubLabel && (
                  <Typography sx={{ fontSize: 10, color: "#6B7C93" }}>{hero.cpdSubLabel}</Typography>
                )}
              </Box>
            </Stack>
          </Box>

          <Box
            sx={{
              position: "relative",
              zIndex: 4,
              display: "flex",
              justifyContent: { xs: "stretch", md: "flex-end" },
              pt: { md: 0.5 },
              pb: { md: 3 },
            }}
          >
            <LeadFormCard key={specialty?.id || "default"} defaultSpecialty={specialty?.id || ""} />
          </Box>
        </Box>
      </Container>
    </Box>
  );
}
